=
{{
JSON.stringify((() => {
  const tarefa = $json;

  function texto(partes) {
    return (partes ?? [])
      .map(parte =>
        parte.plain_text ?? parte.text?.content ?? ''
      )
      .join('')
      .trim();
  }

  function converterBlocos(blocos, nivel = 0) {
    if (!Array.isArray(blocos)) return '';

    return blocos.map(bloco => {
      const dados = bloco[bloco.type] ?? {};
      const conteudo = texto(dados.rich_text);

      const prefixos = {
        heading_1: '#### ',
        heading_2: '##### ',
        heading_3: '###### ',
        bulleted_list_item: '- ',
        numbered_list_item: '1. ',
        quote: '> '
      };

      const prefixo = bloco.type === 'to_do'
        ? (dados.checked ? '- [x] ' : '- [ ] ')
        : (prefixos[bloco.type] ?? '');

      const linha = conteudo
        ? '  '.repeat(nivel) + prefixo + conteudo
        : '';

      const filhos = converterBlocos(
        bloco.children ?? dados.children,
        nivel + 1
      );

      return [linha, filhos].filter(Boolean).join('\n');
    }).filter(Boolean).join('\n\n');
  }

  const taxonomias = tarefa['🏷️ Taxonomia'];

  if (!Array.isArray(taxonomias)) {
    throw new Error(
      'A entrada deste módulo não contém 🏷️ Taxonomia expandida.'
    );
  }

  const funcoes = taxonomias.filter(taxonomia =>
    taxonomia.properties?.['Natureza']?.select?.name === 'Função'
  );

  if (funcoes.length === 0) {
    throw new Error(
      'Não foi encontrada uma taxonomia com Natureza igual a Função na tarefa recebida.'
    );
  }

  return funcoes.map(funcao => ({
    id: funcao.id,
    nome: texto(funcao.properties['Name'].title),
    descricao: texto(funcao.properties['Descrição']?.rich_text),
    conteudo: converterBlocos(funcao.content)
  }));
})())
}}

