          },
          "valor": {
            "type": "string",
            "description": "Conteúdo integral do resultado produzido, pronto para revisão ou utilização. Deve conter somente o conteúdo final, preservando parágrafos e quebras de linha quando aplicável, sem comentários sobre o processo de criação."
          },
          "emoji": {
            "type": "string",
            "description": "Um único emoji Unicode que represente visualmente o resultado como um todo, considerando seu assunto, significado ou finalidade. Escolha um símbolo coerente e representativo, evitando emojis genéricos quando houver uma alternativa mais adequada. Não inclua palavras, explicações ou múltiplos emojis."
          }
        },
        "required": [
          "nome",
          "valor",
          "emoji"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "resultados"
  ],
  "additionalProperties": false
}

