  },
  "properties": {
    "Nome": {
      "title": [
        {
          "type": "text",
          "text": {
            "content": {{ JSON.stringify($json.nome) }}
          }
        }
      ]
    },
    "Conteúdo": {
      "rich_text": [
        {
          "type": "text",
          "text": {
            "content": {{ JSON.stringify($json.valor) }}
          }
        }
      ]
    },
    "📚 Conhecimentos": {
      "relation": {{ JSON.stringify(
        (typeof $('Preparar contexto para a IA').first().json.conhecimentos === 'string'
          ? JSON.parse($('Preparar contexto para a IA').first().json.conhecimentos)
          : $('Preparar contexto para a IA').first().json.conhecimentos ?? []
        ).map(({ id }) => ({ id }))
      ) }}
    },
    "📝 Anotações": {
      "relation": {{ JSON.stringify(
        (typeof $('Preparar contexto para a IA').first().json.anotacoes === 'string'
          ? JSON.parse($('Preparar contexto para a IA').first().json.anotacoes)
          : $('Preparar contexto para a IA').first().json.anotacoes ?? []
        ).map(({ id }) => ({ id }))
      ) }}
    },
    "🏷️ Taxonomias": {
      "relation": {{ JSON.stringify(
        (typeof $('Preparar contexto para a IA').first().json.taxonomias === 'string'
          ? JSON.parse($('Preparar contexto para a IA').first().json.taxonomias)
          : $('Preparar contexto para a IA').first().json.taxonomias ?? []
        ).map(({ id }) => ({ id }))
      ) }}
    },
    "✅ Tarefas": {
      "relation": {{ JSON.stringify([
        { id: $('Receber dados da tarefa').first().json.tarefa.id },
        ...($('Receber dados da tarefa').first().json.tarefa.properties?.['Item pai']?.relation ?? [])
      ]) }}
    }
  }
}

