                  if(
                    day(data) == 3, "Quarta",
                    if(
                      day(data) == 4, "Quinta",
                      if(
                        day(data) == 5, "Sexta",
                        if(
                          day(data) == 6,
                          "Sábado",
                          "Domingo"
                        )
                      )
                    )
                  )
                )
              ),

